const CODE_KR = `#include <algorithm>
#include <cstdio>
#include <numeric>
#include <string>
#include <utility>
#include <vector>

// Union-find with path halving and union by size: near-O(1) per operation.
struct DSU {
    std::vector<int> parent, size;
    explicit DSU(int n) : parent(n), size(n, 1) { std::iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];  // path halving
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {  // false if already in the same set
        a = find(a), b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) std::swap(a, b);
        parent[b] = a;  // hang the smaller tree under the larger
        size[a] += size[b];
        return true;
    }
};

struct Edge { int u, v, w; };

int main() {
    const std::string name = "ABCDEFG";
    std::vector<Edge> edges = {{0, 1, 4}, {0, 3, 2}, {1, 2, 7}, {1, 3, 6}, {1, 4, 3}, {2, 4, 9},
                               {2, 5, 5}, {3, 4, 8}, {3, 6, 10}, {4, 5, 11}, {4, 6, 1}, {5, 6, 12}};
    const int n = 7;
    std::sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) { return a.w < b.w; });
    DSU dsu(n);
    int total = 0, used = 0;
    for (const auto& [u, v, w] : edges) {
        if (dsu.unite(u, v)) {  // u and v were in different trees: the edge is safe
            total += w;
            ++used;
            std::printf("take   %c-%c (%d)\\n", name[u], name[v], w);
            if (used == n - 1) break;  // a spanning tree has exactly V - 1 edges
        } else {
            std::printf("skip   %c-%c (%d)  would close a cycle\\n", name[u], name[v], w);
        }
    }
    std::printf("MST weight %d with %d edges\\n", total, used);
}`;
