const CODE_MAZE = `#include <cstdio>
#include <numeric>
#include <queue>
#include <random>
#include <string>
#include <utility>
#include <vector>

// A perfect maze is a spanning tree of the grid graph: cells are vertices,
// knocked-down walls are edges. Random weights + an MST algorithm = a maze.
struct Maze {
    int R, C;
    std::vector<std::vector<int>> open;  // open[cell] = neighbors joined by a passage
    Maze(int r, int c) : R(r), C(c), open(r * c) {}
    void join(int a, int b) { open[a].push_back(b); open[b].push_back(a); }
};

int find(std::vector<int>& p, int x) {
    while (p[x] != x) x = p[x] = p[p[x]];
    return x;
}

std::vector<std::pair<int, int>> allWalls(int R, int C) {
    std::vector<std::pair<int, int>> walls;
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c) {
            if (c + 1 < C) walls.push_back({r * C + c, r * C + c + 1});
            if (r + 1 < R) walls.push_back({r * C + c, (r + 1) * C + c});
        }
    return walls;
}

Maze kruskalMaze(int R, int C, std::mt19937& rng) {
    Maze m(R, C);
    auto walls = allWalls(R, C);
    for (int i = int(walls.size()) - 1; i > 0; --i)  // Fisher-Yates shuffle
        std::swap(walls[i], walls[rng() % (i + 1)]);
    std::vector<int> p(R * C);
    std::iota(p.begin(), p.end(), 0);
    for (auto [a, b] : walls) {
        int ra = find(p, a), rb = find(p, b);
        if (ra != rb) { p[ra] = rb; m.join(a, b); }  // different regions: knock it down
    }
    return m;
}

Maze primMaze(int R, int C, std::mt19937& rng) {
    Maze m(R, C);
    std::vector<bool> in(R * C, false);
    std::vector<std::pair<int, int>> frontier;  // walls between the maze and outside
    auto addCell = [&](int a) {
        in[a] = true;
        int r = a / C, c = a % C;
        if (r > 0) frontier.push_back({a, a - C});
        if (r + 1 < R) frontier.push_back({a, a + C});
        if (c > 0) frontier.push_back({a, a - 1});
        if (c + 1 < C) frontier.push_back({a, a + 1});
    };
    addCell(0);
    while (!frontier.empty()) {
        size_t k = rng() % frontier.size();  // a random frontier wall
        auto [a, b] = frontier[k];
        frontier[k] = frontier.back();
        frontier.pop_back();
        if (!in[b]) { m.join(a, b); addCell(b); }
    }
    return m;
}

Maze dfsMaze(int R, int C, std::mt19937& rng) {  // "recursive backtracker"
    Maze m(R, C);
    std::vector<bool> seen(R * C, false);
    std::vector<int> stack = {0};
    seen[0] = true;
    while (!stack.empty()) {
        int a = stack.back(), r = a / C, c = a % C;
        std::vector<int> next;
        if (r > 0 && !seen[a - C]) next.push_back(a - C);
        if (r + 1 < R && !seen[a + C]) next.push_back(a + C);
        if (c > 0 && !seen[a - 1]) next.push_back(a - 1);
        if (c + 1 < C && !seen[a + 1]) next.push_back(a + 1);
        if (next.empty()) { stack.pop_back(); continue; }
        int b = next[rng() % next.size()];
        m.join(a, b);
        seen[b] = true;
        stack.push_back(b);
    }
    return m;
}

void print(const Maze& m) {
    for (int r = 0; r < m.R; ++r) {
        std::string top = "+", mid = "|";
        for (int c = 0; c < m.C; ++c) {
            int a = r * m.C + c;
            auto has = [&](int b) { for (int x : m.open[a]) if (x == b) return true; return false; };
            top += (r > 0 && has(a - m.C)) ? "  +" : "--+";
            mid += (c + 1 < m.C && has(a + 1)) ? "   " : "  |";
        }
        std::printf("%s\\n%s\\n", top.c_str(), mid.c_str());
    }
    std::string bottom = "+";
    for (int c = 0; c < m.C; ++c) bottom += "--+";
    std::printf("%s\\n", bottom.c_str());
}

void stats(const char* label, const Maze& m) {
    int passages = 0, deadEnds = 0;
    for (const auto& nb : m.open) { passages += int(nb.size()); deadEnds += nb.size() == 1; }
    std::vector<int> dist(m.R * m.C, -1);  // BFS: solution length corner to corner
    std::queue<int> q;
    dist[0] = 0;
    q.push(0);
    while (!q.empty()) {
        int a = q.front(); q.pop();
        for (int b : m.open[a]) if (dist[b] < 0) { dist[b] = dist[a] + 1; q.push(b); }
    }
    std::printf("%-12s passages %d, dead ends %3d, solution length %d\\n",
                label, passages / 2, deadEnds, dist[m.R * m.C - 1]);
}

int main() {
    std::mt19937 rng(42);
    Maze small = kruskalMaze(6, 12, rng);
    print(small);
    std::printf("30 x 30 mazes (900 cells):\\n");
    stats("Kruskal", kruskalMaze(30, 30, rng));
    stats("Prim", primMaze(30, 30, rng));
    stats("DFS", dfsMaze(30, 30, rng));
}`;
